@startuml

class Location {
  + Address : string
}

class Driver {
  + FirstName : string
  + LastName : string
}

class Vehicle {
  + VehicleNumber : string
}

abstract class Truck {
  + Weight : float
}

abstract class Car {
  + NumberOfSeats : int
}

class Van {}

class Order {
  + OriginLocation : string
  + DestinationLocation : string
  + ExecutionDate : date
}

Location "1" *-- "1..*" Driver
Location "1" *-- "1..*" Vehicle
Vehicle "1" -- "0..1" Driver : drivenBy
Driver "1" -- "0..1" Order : carries
Order "*" -- "1..*" Driver : assignedTo
Order "*" -- "1" Location : origin
Order "*" -- "1" Location : destination

Truck --|> Vehicle
Car --|> Vehicle
Van --|> Vehicle

@enduml

